import java.util.concurrent.locks.*;

class Solution {
    private int green = 1;
    private final ReentrantLock lock = new ReentrantLock();

    public void carArrived(int carId, int roadId, int direction, Runnable turnGreen, Runnable crossCar) {
        lock.lock();
        try {
            if (green != roadId) {
                turnGreen.run();
                green = roadId;
            }
        } finally {
            lock.unlock();
        }
        crossCar.run();
    }
}

