import java.util.concurrent.atomic.AtomicInteger;

class Solution {
    private final AtomicInteger green = new AtomicInteger(1);

    public void carArrived(int carId, int roadId, int direction, Runnable turnGreen, Runnable crossCar) {
        int old = green.getAndSet(roadId);
        if (old != roadId) turnGreen.run();
        crossCar.run();
    }
}

